import React, { useMemo } from 'react'
import { useLoader } from '@react-three/fiber'
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { Interactive } from './parts'

// Generated by tools/avatar/build_pets.py: two roots, each cat in its own bed, both at the origin.
const MODEL = '/models/pets.glb'

const CATS: {
  node: string
  label: string
  position: [number, number, number]
  rotationY: number
}[] = [
  {
    node: 'CatOrange',
    label: 'Asleep, as usual',
    position: [-5.0, -2.75, 2.5],
    rotationY: 0.55,
  },
  {
    node: 'CatSiamese',
    label: 'Supervising',
    position: [-3.15, -2.75, 3.75],
    rotationY: 0.75,
  },
]

export const Pets: React.FC<{ onHover: (label: string | null) => void }> = ({
  onHover,
}) => {
  const gltf = useLoader(GLTFLoader, MODEL)
  const cats = useMemo(() => {
    const scene = gltf.scene.clone(true)
    scene.traverse((o) => {
      if ((o as THREE.Mesh).isMesh) {
        o.castShadow = true
        o.receiveShadow = true
      }
    })
    return CATS.map((c) => ({
      ...c,
      object: scene.getObjectByName(c.node),
    })).filter((c) => c.object)
  }, [gltf])

  return (
    <>
      {cats.map((c) => (
        <group
          key={c.node}
          position={c.position}
          rotation={[0, c.rotationY, 0]}
          scale={1.2}
        >
          <Interactive label={c.label} onHover={onHover} lift={0.04}>
            <primitive object={c.object!} />
          </Interactive>
        </group>
      ))}
    </>
  )
}
